using CaixaLume.Models;
using CaixaLume.Services;

namespace CaixaLume.Forms;

internal sealed class UsuariosForm:Form
{
    private readonly UsuarioService _service=new();
    private readonly DataGridView _grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,AllowUserToAddRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
    public UsuariosForm(){Text="Usuários e permissões";StartPosition=FormStartPosition.CenterParent;MinimumSize=new Size(740,460);Size=new Size(880,560);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(14),ColumnCount=1,RowCount=2};root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};var add=new Button{Text="Novo usuário",AutoSize=true};var edit=new Button{Text="Editar",AutoSize=true};var deactivate=new Button{Text="Desativar",AutoSize=true};bar.Controls.AddRange([add,edit,deactivate]);root.Controls.Add(bar,0,0);root.Controls.Add(_grid,0,1);Controls.Add(root);UiTheme.StyleGrid(_grid);UiTheme.Apply(this);add.Click+=(_,_)=>Edit(null);edit.Click+=(_,_)=>{if(_grid.CurrentRow?.DataBoundItem is UsuarioLinha selected)Edit(selected);};deactivate.Click+=(_,_)=>ChangeActiveSelected();_grid.CellDoubleClick+=(_,_)=>{if(_grid.CurrentRow?.DataBoundItem is UsuarioLinha selected)Edit(selected);};_grid.SelectionChanged+=(_,_)=>{var selected=_grid.CurrentRow?.DataBoundItem as UsuarioLinha;edit.Enabled=selected is not null;deactivate.Enabled=selected is not null;deactivate.Text=selected?.Ativo==false?"Reativar":"Desativar";};LoadRows();}
    private void LoadRows(){_grid.DataSource=_service.Listar();var selected=_grid.CurrentRow?.DataBoundItem as UsuarioLinha;foreach(Button button in Controls.OfType<TableLayoutPanel>().SelectMany(root=>root.Controls.OfType<FlowLayoutPanel>()).SelectMany(bar=>bar.Controls.OfType<Button>()).Where(button=>button.Text is "Editar" or "Desativar" or "Reativar"))button.Enabled=selected is not null;}
    private void Edit(UsuarioLinha? user){using var window=new Form{Text=user is null?"Novo usuário":"Editar usuário",StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,ClientSize=new Size(480,320)};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=2,RowCount=5};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,110));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));var name=new TextBox{Dock=DockStyle.Fill,CharacterCasing=CharacterCasing.Upper,Text=user?.Nome??""};var login=new TextBox{Dock=DockStyle.Fill,Text=user?.Login??""};var role=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};role.Items.AddRange(["OPERADOR","ADMINISTRADOR"]);role.SelectedItem=user?.Perfil??"OPERADOR";var password=new TextBox{Dock=DockStyle.Fill,UseSystemPasswordChar=true,PlaceholderText=user is null?"Mínimo 10 caracteres":"Deixe vazio para manter"};string[] labels=["Nome","Login","Perfil","Senha"];Control[] inputs=[name,login,role,password];for(int i=0;i<inputs.Length;i++){layout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));layout.Controls.Add(new Label{Text=labels[i],AutoSize=true,Anchor=AnchorStyles.Left},0,i);layout.Controls.Add(inputs[i],1,i);}var save=new Button{Text="Salvar usuário",Width=130,Height=36};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));layout.Controls.Add(save,1,4);window.Controls.Add(layout);UiTheme.Apply(window);save.Click+=(_,_)=>{try{_service.Salvar(user?.Id??0,name.Text,login.Text,role.Text,password.Text);window.DialogResult=DialogResult.OK;window.Close();}catch(Exception ex){UiDialog.Warning(window,"Usuários",ex.Message);}};if(window.ShowDialog(this)==DialogResult.OK)LoadRows();}
    private void ChangeActiveSelected(){if(_grid.CurrentRow?.DataBoundItem is not UsuarioLinha user)return;bool reactivate=!user.Ativo;if(!UiDialog.Confirm(this,reactivate?"Reativar usuário":"Desativar usuário",$"{(reactivate?"Reativar":"Desativar")} {user.Login}? O registro será preservado.",!reactivate))return;try{if(reactivate)_service.Reativar(user.Id);else _service.Desativar(user.Id);LoadRows();}catch(Exception ex){UiDialog.Warning(this,"Usuários",ex.Message);}}
}
